class Drawing:
    def __init__(self,w=1440,h=960):
        self.w,self.h=w,h; self.items=[]; self.text_boxes=[]
    def rect(self,x,y,w,h,fill='paper',stroke=None,r=0):
        self.items.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{C.get(fill,fill)}"'+(f' stroke="{C.get(stroke,stroke)}"' if stroke else '')+'/>')
    def line(self,x,y,x2,y2,col='line',width=1):
        self.items.append(f'<path d="M{x} {y}H{x2}" stroke="{C.get(col,col)}" stroke-width="{width}"/>' if y==y2 else f'<path d="M{x} {y}L{x2} {y2}" stroke="{C.get(col,col)}" stroke-width="{width}"/>')
    def text(self,x,y,value,size=14,fill='ink',weight=400,maxw=None):
        value=str(value); chevron='▾' in value; value=value.replace('▾','').rstrip(); font=ImageFont.truetype(str(FONT),size)
        if maxw:
            while font.getlength(value)>maxw and len(value)>1:
                value=value[:-2]+'…' if value.endswith('…') else value[:-1]+'…'
        self.items.append(f'<text x="{x}" y="{y}" fill="{C.get(fill,fill)}" font-family="Golos Text" font-size="{size}" font-weight="{weight}">{escape(value)}</text>')
        if chevron:
            xx=x+font.getlength(value)+9;self.items.append(f'<path d="M{xx} {y-6}l4 4 4-4" fill="none" stroke="{C.get(fill,fill)}" stroke-width="1.5"/>')
        self.text_boxes.append((x,y,font.getlength(value),size,value))
    def paragraph(self,x,y,text,width,size=14,col='muted',leading=22,maxlines=6):
        font=ImageFont.truetype(str(FONT),size); lines=[]; row=''
        for word in text.split():
            if row and font.getlength(row+' '+word)>width: lines.append(row); row=word
            else: row=(row+' '+word).strip()
        if row:lines.append(row)
        for i,line in enumerate(lines[:maxlines]):self.text(x,y+i*leading,line,size,col,maxw=width)
        return y+len(lines[:maxlines])*leading
    def button(self,x,y,label,primary=False,width=None,danger=False):
        width=width or max(88,int(ImageFont.truetype(str(FONT),13).getlength(label))+30)
        height=44 if self.w<600 else 36
        self.rect(x,y,width,height,'red' if danger else ('blue' if primary else 'paper'),None if primary or danger else 'line',5)
        self.text(x+15,y+height/2+5,label,13,'#FFFFFF' if primary or danger else 'ink',500,maxw=width-25)
        return width
    def pill(self,x,y,label,kind='slate'):
        pair={'success':('greenbg','green'),'warning':('amberbg','amber'),'error':('redbg','red'),'info':('pale','blue'),'slate':('slate','muted')}[kind]
        width=int(ImageFont.truetype(str(FONT),12).getlength(label))+22
        self.rect(x,y,width,25,pair[0],r=4); self.text(x+10,y+17,label,12,pair[1],500)
        return width
    def field(self,x,y,label,value,width=360,error=None):
        self.text(x,y,label,12,'muted',500);self.rect(x,y+10,width,40,'paper','red' if error else 'line',4)
        self.text(x+12,y+36,value,14,maxw=width-26)
        if error:self.text(x,y+70,error,12,'red',maxw=width)
    def save(self,path,title):
        header=f'<svg xmlns="http://www.w3.org/2000/svg" width="{self.w}" height="{self.h}" viewBox="0 0 {self.w} {self.h}" role="img" aria-label="{escape(title)}"><title>{escape(title)}</title><desc>Редактируемый макет Кей Календаря. Все данные вымышлены. Не является приложением.</desc>'
        path.write_text(header+''.join(self.items)+'</svg>',encoding='utf-8')

