def table(d,cols,rows,x=216,y=225,width=1192,rowh=53,ratios=None):
    ratios=ratios or [1]*len(cols); widths=[width*r/sum(ratios) for r in ratios]
    d.rect(x,y,width,42,'slate');cx=x
    for col,w in zip(cols,widths):d.text(cx+14,y+26,col,12,'muted',500,maxw=w-22);cx+=w
    for i,row in enumerate(rows):
        yy=y+42+i*rowh;d.rect(x,yy,width,rowh,'paper');d.line(x,yy+rowh,x+width,yy+rowh)
        cx=x
        for j,(v,w) in enumerate(zip(row,widths)):
            if isinstance(v,tuple):d.pill(cx+12,yy+14,v[0],v[1])
            else:d.text(cx+14,yy+31,v,13,'blue' if j==0 else 'ink',500 if j==0 else 400,maxw=w-24)
            cx+=w

def form(d,fields,action='Сохранить',note='',x=240,y=247,width=770):
    for i,(label,value) in enumerate(fields):
        col=i%2;row=i//2;d.field(x+col*(width/2+14),y+row*88,label,value,width/2-14)
    end=y+((len(fields)+1)//2)*88+8
    if note:end=d.paragraph(x,end,note,width,13,leading=21,maxlines=4)+12
    d.button(x,end,action,True);d.button(x+max(150,len(action)*8+40),end,'Отмена')
    return end

