def render_special(d,s):
    if render_detail(d,s,table,form):return
    kind=s['kind']
    if kind in ['calendar','calfilters','conflict']:calendar(d,{'calendar':'default','calfilters':'filters','conflict':'conflict'}[kind]);return
    if kind in ['reservation','reservation-new']:reservation(d,kind.endswith('new'));return
