def build():
    ref=json.loads((ROOT/'requirements/reference.json').read_text(encoding='utf-8-sig'))['features']
    saas=json.loads((ROOT/'requirements/saas.json').read_text(encoding='utf-8-sig'))['requirements']
    requirements=ref+saas
    screens=[]
    for domain,defs in SCREEN_DEFS.items():
        for n,(title,kind) in enumerate(defs,1):
            sid=f'SCR-{domain}-{n:02}'
            related=[f for f in requirements if sid in f['screen_ids']]
            scenario=related[0]['purpose'] if related else 'Поддерживающее состояние раздела'
            s={'id':sid,'title':title,'kind':kind,'subtitle':'Дом у парка · демонстрационное рабочее пространство',
               'scenario':scenario,'detail':(' '.join(related[0].get('rules',[])))[:340] if related else 'Откройте строку для просмотра деталей; действия зависят от прав и состояния.',
               'requirement_ids':[f['id'] for f in related], 'source':f'source/{sid}.svg','preview':f'exports/{sid}.png',
               'viewport':{'width':1440,'height':960},'state_refs':['STATE-01','STATE-02','STATE-03','STATE-04','STATE-05','STATE-06'],
               'responsive_refs':['SCR-MOBILE-01','SCR-MOBILE-02','SCR-TABLET-01'],
               'component_refs':['CMP-TABLE','CMP-FIELD','CMP-BUTTON','CMP-STATUS','CMP-DIALOG']}
            d=Drawing();shell(d,s);render_special(d,s);d.save(OUT/(sid+'.svg'),title);screens.append(s)
    # Shared state board uses actual messages, actions, focus and recovery paths.
    state_screens=[]
    states=[('STATE-01','Загрузка','Получаем актуальную занятость.','Скелетон сохраняет ширины колонок. Повторный запрос не очищает фильтры.','loading'),
            ('STATE-02','Пока нет бронирований','Добавьте первую бронь или импортируйте данные.','Пустой поиск предлагает сброс фильтров; пустая организация ведёт к первому объекту.','empty'),
            ('STATE-03','Не удалось загрузить данные','Проверьте соединение и повторите запрос.','Черновик сохранён. Время последнего успешного чтения видно; запись офлайн запрещена.','error'),
            ('STATE-04','Недостаточно прав','Обратитесь к администратору организации.','Не показывать гостевые данные, сумму или название скрытого объекта.','access'),
            ('STATE-05','Запись уже изменена','Сравните текущую версию со своим черновиком.','Автоматическое затирание запрещено. Повторное сохранение проходит новую проверку.','version'),
            ('STATE-06','Подключение требует доступа','Договор или права поставщика ещё не подтверждены.','Кнопка синхронизации недоступна. Показаны конкретное условие и ответственный.','blocked')]
    for sid,title,body,rule,kind in states:
        d=Drawing();s={'id':sid,'title':title,'subtitle':'Поведение состояния во всех разделах','scenario':rule};shell(d,s)
        d.rect(362,250,900,532,'paper','line',8);d.pill(394,281,{'loading':'Загрузка','empty':'Нет данных','error':'Ошибка сети','access':'Доступ ограничен','version':'Версия изменилась','blocked':'Нужен допуск'}[kind],'error' if kind in ['error','version'] else 'info')
        d.text(394,362,title,26,weight=600);d.paragraph(394,411,body,788,17);d.paragraph(394,477,rule,788,14)
        if kind=='loading':
            for i,w in enumerate([756,622,700]):d.rect(394,553+i*38,w,18,'slate',r=3)
        else:d.button(394,618,{'empty':'Создать бронирование','error':'Повторить','access':'Вернуться в календарь','version':'Сравнить версии','blocked':'Открыть условия'}[kind],True,277);d.button(694,618,'Закрыть',False,135)
        d.text(394,746,'Tab: основной путь → альтернативы • Escape: закрыть • Фокус возвращается к инициатору',12,'muted')
        d.save(OUT/(sid+'.svg'),title);state_screens.append({'id':sid,'title':title,'source':f'source/{sid}.svg','preview':f'exports/{sid}.png','message':body,'recovery':rule})
    build_components();build_responsive();build_assets();variants=build_variants(screens)
    (ROOT/'design/screens.json').write_text(json.dumps({'version':'1.0','screens':screens,'shared_states':state_screens,'variants':variants},ensure_ascii=False,indent=2),encoding='utf-8')
    tokens={'$description':'Кей Календарь. Семантические дизайн-токены.','color':{k:{'$type':'color','$value':v} for k,v in C.items()},'font':{'family':'Golos Text','fallback':'Arial, sans-serif','body':14,'small':12,'table':13,'title':26,'weights':[400,500,600]},'space':[4,8,12,16,24,32,48],'radius':{'control':4,'panel':5,'dialog':8},'size':{'sidebar':184,'header':64,'rowDefault':56,'rowCompact':40,'targetMin':44,'input':40,'calendarDay':79},'zIndex':{'base':0,'stickyHeader':10,'stickyRowLabel':20,'popover':40,'drawer':60,'dialog':80,'toast':100},'motion':{'hoverMs':100,'drawerMs':180,'dialogMs':120,'statusMs':150,'easing':'cubic-bezier(0.2,0,0,1)','reducedMotion':'none','skeleton':'static'}}
    (ROOT/'design/tokens.json').write_text(json.dumps(tokens,ensure_ascii=False,indent=2),encoding='utf-8')
    index=['# Макеты и исходники','', 'Все SVG редактируемы: текст, формы, линии и слои остаются векторными. Установите [Golos Text](../assets/fonts/GolosText-variable.ttf) перед редактированием. PNG предназначены для просмотра. Данные синтетические.','', '| Экран | Исходник | Просмотр |','|---|---|---|']
    for s in screens+state_screens+variants:index.append(f"| {s['id']} · {s['title']} | [SVG]({s['source']}) | [PNG]({s['preview']}) |")
    index+=['','Дополнительные листы: [компоненты](source/CMP-LIBRARY.svg), [мобильный календарь](source/SCR-MOBILE-01.svg), [мобильная бронь](source/SCR-MOBILE-02.svg), [планшет](source/SCR-TABLET-01.svg), [широкий экран](source/SCR-WIDE-01.svg).','', 'Правила поведения: [спецификация](specification.md). Машиночитаемая карта: [screens.json](screens.json).']
    (ROOT/'design/README.md').write_text('\n'.join(index)+'\n',encoding='utf-8')
    print(f'Generated {len(screens)} editable desktop screens, {len(state_screens)} state screens, components and responsive artboards.')

